// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 amount, uint256 ts, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: play() only accepts exactly one ticket (TICKET_AMOUNT = 10 wei).
        amount = bound(amount, 10, 10);
        ts = bound(ts, 1, 2 ** 64 - 1);
        vm.assume(actor != address(0));

        vm.warp(ts);
        vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // General invariant: recorded pot never exceeds the Ether actually held.
            assertTrue(c.pot() <= address(c).balance);
        } else {
            assertTrue(true);
        }
    }
}
